        vaultTested.claimAndRequestDeposit(0, user1.addr, "");
        console.log(vaultTested.pendingDepositRequest(user1.addr));
        require(vaultTested.pendingDepositRequest(user1.addr) == 0);
        vm.stopPrank();
    }
```
